import React, { useState } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import './Layout.css';

const NAV_ITEMS = [
  { path: '/', label: 'Tableau de bord', icon: '📊', exact: true },
  { path: '/personnel', label: 'Personnel', icon: '👥', roles: ['super_admin', 'assistant_admin', 'direction'] },
  { path: '/absences', label: 'Absences & Congés', icon: '📅', roles: ['super_admin', 'assistant_admin', 'direction'] },
  { path: '/volontaires', label: 'Volontaires', icon: '🤝', roles: ['super_admin', 'responsable_volontaires', 'direction'] },
  { path: '/stock', label: 'Gestion du Stock', icon: '📦', roles: ['super_admin', 'responsable_stock', 'direction'] },
  { path: '/projets', label: 'Projets', icon: '🎯' },
  { path: '/utilisateurs', label: 'Utilisateurs', icon: '🔐', roles: ['super_admin'] },
];

const ROLE_LABELS = {
  super_admin: 'Administrateur Système',
  direction: 'Direction',
  assistant_admin: 'Assistant Administration',
  responsable_stock: 'Responsable Stock',
  responsable_volontaires: 'Responsable Volontaires',
  coordinateur: 'Coordinateur',
  utilisateur: 'Utilisateur'
};

export default function Layout() {
  const { user, logout, hasRole } = useAuth();
  const navigate = useNavigate();
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);

  const handleLogout = () => { logout(); navigate('/login'); };

  const visibleItems = NAV_ITEMS.filter(item =>
    !item.roles || item.roles.some(r => r === user?.role)
  );

  return (
    <div className={`layout ${collapsed ? 'sidebar-collapsed' : ''} ${mobileOpen ? 'mobile-open' : ''}`}>
      {/* Overlay mobile */}
      {mobileOpen && <div className="overlay" onClick={() => setMobileOpen(false)} />}

      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-header">
          <div className="logo">
            <div className="logo-icon">✝</div>
            {!collapsed && (
              <div className="logo-text">
                <span className="logo-title">LHM Madagascar</span>
                <span className="logo-subtitle">Feon'ny Filazantsara</span>
              </div>
            )}
          </div>
          <button className="collapse-btn" onClick={() => setCollapsed(!collapsed)} title="Réduire le menu">
            {collapsed ? '›' : '‹'}
          </button>
        </div>

        <nav className="sidebar-nav">
          {visibleItems.map(item => (
            <NavLink
              key={item.path}
              to={item.path}
              end={item.exact}
              className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
              onClick={() => setMobileOpen(false)}
              title={collapsed ? item.label : ''}
            >
              <span className="nav-icon">{item.icon}</span>
              {!collapsed && <span className="nav-label">{item.label}</span>}
            </NavLink>
          ))}
        </nav>

        <div className="sidebar-footer">
          {!collapsed && (
            <div className="user-info">
              <div className="user-avatar">{user?.prenom?.[0]}{user?.nom?.[0]}</div>
              <div className="user-details">
                <span className="user-name">{user?.prenom} {user?.nom}</span>
                <span className="user-role">{ROLE_LABELS[user?.role] || user?.role}</span>
              </div>
            </div>
          )}
          <button className="logout-btn" onClick={handleLogout} title="Se déconnecter">
            <span>🚪</span>
            {!collapsed && <span>Déconnexion</span>}
          </button>
        </div>
      </aside>

      {/* Main */}
      <div className="main-wrapper">
        <header className="topbar">
          <button className="mobile-menu-btn" onClick={() => setMobileOpen(!mobileOpen)}>☰</button>
          <div className="topbar-left">
            <h1 className="page-title" id="page-title">Bienvenue</h1>
          </div>
          <div className="topbar-right">
            <div className="topbar-user">
              <div className="user-avatar-sm">{user?.prenom?.[0]}{user?.nom?.[0]}</div>
              <span className="topbar-name">{user?.prenom} {user?.nom}</span>
            </div>
          </div>
        </header>

        <main className="main-content">
          <Outlet />
        </main>
      </div>
    </div>
  );
}
